import sys
sys.setrecursionlimit(300000)

def main():
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx]); idx += 1

    c = [0] * (n + 1)
    for i in range(1, n + 1):
        c[i] = int(input[idx]); idx += 1

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(input[idx]); idx += 1
        v = int(input[idx]); idx += 1
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                children[u].append(v)
                stack.append(v)

    is_leaf = [False] * (n + 1)
    for i in range(2, n + 1):
        if len(children[i]) == 0:
            is_leaf[i] = True

    dp = [0] * (n + 1)
    cnt = [0] * (n + 1)

    for u in reversed(order):
        if is_leaf[u]:
            dp[u] = 0
            cnt[u] = 1
        else:
            min_cost = float('inf')
            min_cnt = 0
            sum_dp = 0
            total_leaves = 0
            for v in children[u]:
                sum_dp += dp[v]
                total_leaves += cnt[v]

            if total_leaves == 0:
                dp[u] = 0
                cnt[u] = 1
            else:
                dp[u] = sum_dp
                cnt[u] = total_leaves

                if c[u] < dp[u]:
                    dp[u] = c[u]
                    cnt[u] = 1

                elif c[u] == dp[u]:
                    pass

    root_cost = dp[1]

    if root_cost == float('inf'):
        root_cost = 0

    needed = [False] * (n + 1)

    def dfs_needed(u, target_cost):
        if is_leaf[u]:
            return target_cost == 0

        if target_cost == 0:
            needed[u] = True
            return True

        if c[u] == target_cost:
            needed[u] = True
            return True

        sum_child = 0
        for v in children[u]:
            sum_child += dp[v]

        if sum_child == target_cost:
            needed[u] = True
            for v in children[u]:
                if not dfs_needed(v, dp[v]):
                    return False
            return True
        else:
            return False

    dfs_needed(1, root_cost)

    result_vertices = []
    for i in range(1, n + 1):

        if is_leaf[i]:
            if dp[i] == 0 and (root_cost == 0 or (not is_leaf[1] and sum(dp[v] for v in children[1]) == root_cost)):
                if needed[i]:
                    result_vertices.append(i)
                continue

        if needed[i]:
            result_vertices.append(i)

    result_vertices.sort()

    print(f"{root_cost} {len(result_vertices)}")
    print(" ".join(map(str, result_vertices)))

if __name__ == "__main__":
    main()
